import { Component, Input, OnChanges, OnInit, SimpleChanges } from '@angular/core';
import { VariablesService } from '../../../core/services/variables.service';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'icon',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './icon.component.html',
  styleUrl: './icon.component.scss'
})
export class IconComponent implements OnChanges, OnInit {
  @Input() name: string = '';
  @Input() type: string = 'comnicn';
  iconUnicode: string = '';

  constructor(private readonly variablesService: VariablesService) { }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['name'] || changes['type']) {
      this.updateIconUnicode();
    }
  }

  ngOnInit(): void {
    this.updateIconUnicode();
  }

  private updateIconUnicode(): void {
    this.iconUnicode = this.variablesService.getIconUnicode(this.name, this.type);
  }

}
